def search_issues(query):
    # Search API
    items = []
    page = 1

    while True:
        print(f"Searching issues: {query} (page {page})...", file=sys.stderr)
        data = get_json("https://api.github.com/search/issues", {
            "q": query,
            "per_page": "100",
            "page": str(page)
        })

        # Search returns {'items': [...], 'total_count': ...}
        if not data or 'items' not in data:
            break

        current_items = data['items']
        if not current_items:
            break

        items.extend(current_items)

        if len(items) >= data.get('total_count', 0):
            break

        page += 1
        if page > 10: break # Safety limit (1000 items)

    return items

def fetch_issues():
    # 1. Created in Dec
    query_created = f"repo:{REPO} is:issue created:2024-12-01..2024-12-31"
    created_issues = search_issues(query_created)

    # 2. Closed in Dec
    query_closed = f"repo:{REPO} is:issue closed:2024-12-01..2024-12-31"
    closed_issues = search_issues(query_closed)

    return created_issues, closed_issues

def analyze(prs, issue_data):
    created_issues, closed_issues = issue_data

    # --- PR Analysis ---
    # prs are already filtered to created in Dec
    pr_total = len(prs)
    pr_merged = 0
    pr_closed = 0
    merge_times = []
    authors = {}

    for pr in prs:
        # Check merge status
        is_merged = pr.get('merged_at') is not None

        if is_merged:
            pr_merged += 1
            created = parse_date(pr['created_at'])
            merged = parse_date(pr['merged_at'])
            if created and merged:
                delta = merged - created
                merge_times.append(delta.total_seconds() / 86400.0) # days
        elif pr['state'] == 'closed':
            # Closed and not merged
            pr_closed += 1

        # Author
        user = pr['user']['login']
        authors[user] = authors.get(user, 0) + 1

    avg_merge_days = 0.0
    if merge_times:
        avg_merge_days = sum(merge_times) / len(merge_times)

    top_contributor = None
    if authors:
        top_contributor = max(authors, key=authors.get)

    # --- Issue Analysis ---
    issue_created_total = len(created_issues)
    issue_bug_count = 0

    for issue in created_issues:
        labels = [l['name'].lower() for l in issue.get('labels', [])]
        if any('bug' in l for l in labels):
            issue_bug_count += 1

    issue_resolved_bugs = 0
    for issue in closed_issues:
        labels = [l['name'].lower() for l in issue.get('labels', [])]
        if any('bug' in l for l in labels):
            issue_resolved_bugs += 1

    report = {
        "pr": {
            "total": pr_total,
            "merged": pr_merged,
            "closed": pr_closed,
            "avg_merge_days": round(avg_merge_days, 1),
            "top_contributor": top_contributor if top_contributor else ""
        },
        "issue": {
            "total": issue_created_total,
            "bug": issue_bug_count,
            "resolved_bugs": issue_resolved_bugs
        }
    }

    return report

